// src/app/datenschutz/page.js
//
// Datenschutzerklärung der ÖkoInvest GmbH (DSGVO, österreichisches DSG).
// Beschreibt die tatsächlich eingesetzten Verarbeitungen dieser Website:
// Hosting, Server-Logs, Anfragen (POST /api/anfrage -> Vorgang im ERP),
// Portal-Konto & Rollen, Anmeldung/Sitzungen/Geräte/2FA, Organisationen,
// Benachrichtigungen, CRM, Termine, Support, Dokumente, Projektbörse (NDA-
// Protokoll, Deal-Room, Datenraum), elektronische Unterschrift, Closing und
// Grundbuch, Rechner (lokal), KI-Assistent, KYC/KYB, Online-Identifizierung,
// Bonität, Register, Flächenakquise (Geodaten, Grundbuch, Brief), Energie-
// beschaffung, Finanzierung/Bank-Portal, Anlagen-Monitoring, Finanzen,
// Projektentwicklung/Gutachter, Live-Strommarktdaten (Energy-Charts,
// serverseitig), Cookie-Banner und Google Analytics 4 (nur nach Einwilligung,
// siehe src/components/Statistik/GoogleAnalytics.js und src/components/Cookies).
//
// ENTWURF zur datenschutzrechtlichen Prüfung (Stand Ausbaustufe 5).
// PLATZHALTER (sichtbar markiert, vor Livegang ersetzen):
//  - Datenschutzkontakt (E-Mail bzw. Datenschutzbeauftragter, falls bestellt)
//  - Hosting-Anbieter der Website und Betreiber/Standort des ERP-Systems
//  - Mailanbieter, Backup-Speicher, Server der Dienste (Geodaten, Messdaten)
//  - Identitätsanbieter, Auskunftei(en), Verrechnungsstelle Grundbuch/Firmenbuch
//  - Videokonferenzdienst für Beratungstermine
//  - Speicherfristen, die im Löschkonzept noch festzulegen sind
// Es werden bewusst KEINE abgeschlossenen AV-Verträge behauptet: Formulierungen
// „auf Grundlage eines Vertrags nach Art. 28 DSGVO“ beschreiben die Pflicht,
// die vor Einsatz des jeweiligen Anbieters erfüllt sein muss (GO-LIVE.md, Abschn. 9).
// TODO rechtlich prüfen: Löschfristen (Server-Logs, Anfragen ohne Vertrag,
// NDA-Protokolle, Akquise-Sperrliste, Monitoring) mit der tatsächlichen
// Konfiguration (site_config „oekoinvest_loeschfristen“) abgleichen;
// Rollenverteilung Identitätsanbieter (Auftragsverarbeiter oder eigener
// Verantwortlicher) und Verpflichtetenstellung nach GwG klären.

import Link from "next/link";
import LegalShell from "@/components/Reusable/LegalShell";
import { GESELLSCHAFT, KONTAKT, abs } from "@/data/site";

const PAGE_URL = abs("/datenschutz");
const TITEL = "Datenschutzerklärung | ÖkoInvest";
const BESCHREIBUNG =
  "Wie die ÖkoInvest GmbH personenbezogene Daten verarbeitet: Anfragen, Portal, Projektbörse, Signatur, Akquise, Energiebeschaffung, Finanzierung und Ihre Rechte.";

/** Datum der letzten inhaltlichen Überarbeitung */
const STAND = "30. September 2026";

export const metadata = {
  title: TITEL,
  description: BESCHREIBUNG,
  alternates: { canonical: PAGE_URL },
  robots: { index: true, follow: true },
  openGraph: {
    type: "website",
    locale: "de_AT",
    url: PAGE_URL,
    siteName: "ÖkoInvest",
    title: TITEL,
    description: BESCHREIBUNG,
    images: [{ url: abs("/img/solarpark-himmel.jpg"), alt: "Solarpark unter blauem Himmel" }],
  },
};

/** Sichtbar markierter Platzhalter – vor Livegang ersetzen. */
function Platzhalter({ children }) {
  return <mark className="rounded-md bg-sun-300/40 px-1.5 py-0.5 font-semibold text-ink-900">[Platzhalter: {children}]</mark>;
}

const G = GESELLSCHAFT;

/** Speicherfristen. Werte in eckigen Klammern sind im Löschkonzept noch festzulegen (Platzhalter). */
const FRISTEN = [
  ["Server-Logdaten", "in der Regel 14 Tage, bei Sicherheitsvorfällen bis zur Klärung"],
  ["Anfragen ohne Vertragsabschluss", "bis zu 3 Jahre nach der letzten Kommunikation, sofern Sie nicht früher die Löschung verlangen"],
  ["Portal-Konto", "für die Dauer der Registrierung; nach Löschung des Kontos Entfernung binnen 30 Tagen, soweit keine Aufbewahrungspflicht besteht"],
  ["Beendete Sitzungen und nicht angenommene Einladungen", "30 Tage"],
  ["Anmeldehistorie (erfolgreiche und fehlgeschlagene Anmeldungen)", "180 Tage"],
  ["Benachrichtigungen im Portal", "gelesene 12 Monate, alle übrigen höchstens 24 Monate"],
  ["NDA-Protokolle, Datenraum-Zugriffe und Exposé-Abrufe", "für die Dauer der Vertraulichkeitsverpflichtung zuzüglich der gesetzlichen Verjährungsfristen"],
  ["Signaturprotokolle und signierte Dokumente", "solange das zugrunde liegende Dokument aufzubewahren ist, mindestens bis zum Ablauf der Verjährungsfristen"],
  ["Termine", "Terminangaben bis zu 12 Monate nach dem Termin, soweit daraus kein Vorgang oder Vertrag entsteht; Verwaltungslinks werden mit dem Termin ungültig"],
  ["Support-Tickets", "bis zu 3 Jahre nach Abschluss des Tickets, soweit sie nicht zu einem Vertrag gehören"],
  ["Protokoll des KI-Assistenten (ohne Inhalte)", "12 Monate"],
  ["KYC/KYB-Unterlagen und Personenangaben", "5 Jahre ab Schluss des Kalenderjahres, in dem die Geschäftsbeziehung endet (abgelehnte Fälle ab Ablehnung)"],
  ["Bonitätsauskünfte", "[Platzhalter: bis zu 12 Monate nach Abschluss der Prüfung bzw. für die Dauer des Vertrags – wird im Löschkonzept festgelegt]"],
  ["Akquise: Eigentümerdaten aus dem Grundbuch ohne Rückmeldung", "12 Monate nach dem Anschreiben, danach Löschung"],
  ["Akquise: Sperrvermerk nach Widerspruch", "solange erforderlich, um den Widerspruch zu beachten (nur Name, Anschrift, Grundstücksbezug, Datum)"],
  ["Energiebeschaffung: Lastgänge, Abnahmestellen, Beschaffungsvollmacht", "für die Dauer des Beschaffungsauftrags; Vollmacht-Nachweis zuzüglich der Verjährungsfristen"],
  ["Bankenpaket und Abrufprotokolle der Banken", "für die Dauer der Finanzierungsanfrage bzw. des Kreditverhältnisses zuzüglich der Verjährungsfristen"],
  ["Messdaten der Anlagen (Monitoring)", "[Platzhalter: hochaufgelöste Werte z. B. 24 Monate, verdichtete Werte für die Vertragslaufzeit – wird im Löschkonzept festgelegt]"],
  ["Abrechnungsrelevante Zählerstände, Rechnungen, Gutschriften, Zahlungsläufe", "Österreich 7 Jahre (§ 132 BAO, § 212 UGB), bei Grundstücksbezug bis zu 22 Jahre; Deutschland bis zu 10 Jahre (§ 147 AO, § 257 HGB; Buchungsbelege nach aktuellem Stand 8 Jahre); Schweiz 10 Jahre (Art. 958f OR)"],
  ["Vertrags-, Provisions- und Buchhaltungsunterlagen", "7 Jahre nach § 132 BAO bzw. § 212 UGB, bei Grundstücksbezug ggf. länger; für deutsche und schweizerische Gesellschaften die dortigen Fristen (siehe oben)"],
  ["Grundbuch- und Dienstbarkeitsakten", "für die Laufzeit der Dienstbarkeit bzw. des Nutzungsvertrags zuzüglich der Verjährungsfristen"],
  ["Einwilligung (Cookie-Einstellungen)", "12 Monate, danach fragen wir erneut"],
  ["Google-Analytics-Cookies", "bis zu 2 Jahre bzw. bis zum Widerruf; Ereignisdaten in Google Analytics höchstens 14 Monate"],
];

export default function DatenschutzPage() {
  return (
    <LegalShell
      titel="Datenschutzerklärung"
      pfad="/datenschutz"
      lead="Welche personenbezogenen Daten wir auf dieser Website, im Portal, in der Projektbörse und in unseren Fachmodulen verarbeiten, wozu, auf welcher Rechtsgrundlage – und welche Rechte Sie haben."
    >
      <nav aria-label="Inhalt der Datenschutzerklärung" className="mb-10 rounded-2xl bg-sand-50 p-5 ring-1 ring-ink-200/60 md:p-6">
        <p className="font-display text-[16px] font-bold text-ink-900">Schnellzugriff</p>
        <ul className="mt-3 grid gap-x-6 gap-y-1.5 text-[15px] sm:grid-cols-2">
          <li><a href="#konto">Portal, Anmeldung und Teams (6–6g)</a></li>
          <li><a href="#boerse">Projektbörse, Signatur, Closing (7–7b)</a></li>
          <li><a href="#pruefungen">Identität, Bonität, Register (8b–8e)</a></li>
          <li><a href="#akquise">Flächenakquise und Grundbuch (8f)</a></li>
          <li><a href="#energie">Energiebeschaffung (8g)</a></li>
          <li><a href="#finanzierung">Finanzierung, Monitoring, Abrechnung (8h–8j)</a></li>
          <li><a href="#empfaenger">Empfänger (12)</a></li>
          <li><a href="#speicherdauer">Speicherdauer (13) und Ihre Rechte (14)</a></li>
        </ul>
      </nav>

      <h2>1. Verantwortlicher</h2>
      <p>Verantwortlich für die Datenverarbeitung auf dieser Website und in unserem Portal ist:</p>
      <address className="not-italic">
        <strong>{G.name}</strong>
        <br />

import Link from "next/link";
import { ArrowRight, FileText, Mail, Phone } from "lucide-react";
import Breadcrumbs from "@/components/ui/Breadcrumbs";
import { Eyebrow } from "@/components/ui/SectionHeading";
import { KONTAKT } from "@/data/site";

const RECHTLICHES = [
  { name: "Impressum", href: "/impressum" },
  { name: "Datenschutz", href: "/datenschutz" },
  { name: "Nutzungsbedingungen", href: "/nutzungsbedingungen" },
  { name: "Barrierefreiheit", href: "/barrierefreiheit" },
];

/**
 * Rahmen für Rechtstexte: kompakter dunkler Kopf, lesbare Spalte, Seitenleiste
 * mit Navigation zwischen den Rechtstexten und Kontakt. `.ov-legal`
 * vereinheitlicht die Typografie des Rechtstextes.
 *
 * Kontaktbox: Telefon und E-Mail erscheinen nur, wenn sie in
 * src/data/site.js (KONTAKT) freigegeben sind – sonst Verweis auf /kontakt.
 */
export default function LegalShell({ titel, pfad, lead, children }) {
  return (
    <div>
      <section className="ov-noise relative isolate overflow-hidden bg-navy-950 text-white">
        <div aria-hidden="true" className="ov-grid-bg absolute inset-0 -z-10" />
        <div aria-hidden="true" className="absolute -right-24 -top-24 -z-10 h-[360px] w-[360px] rounded-full bg-ov-500/20 blur-[120px]" />
        <div className="ov-container pb-14 pt-8 md:pb-20 md:pt-12">
          <Breadcrumbs dark items={[{ name: titel }]} className="ov-hero-in mb-10" />
          <div className="ov-hero-in" style={{ "--ov-delay": "60ms" }}>
            <Eyebrow dark className="mb-4">Rechtliches</Eyebrow>
          </div>
          <h1 className="ov-h1 ov-hero-in" style={{ "--ov-delay": "120ms" }}>{titel}</h1>
          {lead && <p className="ov-lead ov-hero-in mt-5 max-w-2xl text-white/65" style={{ "--ov-delay": "180ms" }}>{lead}</p>}
        </div>
      </section>

      <div className="bg-sand-50">
        <div className="ov-container grid gap-10 py-12 md:py-16 lg:grid-cols-[1fr_280px] lg:gap-14">
          <article className="ov-legal min-w-0 rounded-[2rem] bg-white p-6 shadow-sm ring-1 ring-ink-200/60 md:p-12">{children}</article>

          <aside className="lg:sticky lg:top-28 lg:self-start">
            <nav aria-label="Rechtstexte" className="rounded-3xl bg-white p-5 ring-1 ring-ink-200/60">
              <p className="px-2 text-[12px] font-semibold uppercase tracking-[0.14em] text-ink-500">Rechtstexte</p>
              <ul className="mt-3 space-y-1">
                {RECHTLICHES.map((r) => (
                  <li key={r.href}>
                    <Link
                      href={r.href}
                      aria-current={pfad === r.href ? "page" : undefined}
                      className={`flex items-center gap-2.5 rounded-xl px-3 py-2.5 text-[15px] font-medium transition-colors ${pfad === r.href ? "bg-ov-50 text-ov-800" : "text-ink-700 hover:bg-ink-50"}`}
                    >
                      <FileText aria-hidden="true" className="h-4 w-4" />
                      {r.name}
                    </Link>
                  </li>
                ))}
              </ul>
            </nav>
            <div className="mt-4 rounded-3xl bg-navy-950 p-6 text-white">
              <p className="font-display text-[17px] font-bold">Fragen zu diesem Text?</p>
              {KONTAKT.telefon && (
                <a href={KONTAKT.telefonHref || `tel:${KONTAKT.telefon.replace(/[^+\d]/g, "")}`} className="mt-4 flex items-center gap-2.5 text-[14.5px] text-white/85 hover:text-white">
                  <Phone aria-hidden="true" className="h-4 w-4 text-ov-300" /> {KONTAKT.telefon}
                </a>
              )}
              {KONTAKT.email && (
                <a href={`mailto:${KONTAKT.email}`} className="mt-2 flex items-center gap-2.5 break-all text-[14.5px] text-white/85 hover:text-white">
                  <Mail aria-hidden="true" className="h-4 w-4 shrink-0 text-ov-300" /> {KONTAKT.email}
                </a>
              )}
              {!KONTAKT.telefon && !KONTAKT.email && (
                <p className="mt-2 text-[14px] leading-relaxed text-white/65">Schreiben Sie uns über das Kontaktformular – wir antworten schriftlich.</p>
              )}
              <Link href="/kontakt" className="mt-4 inline-flex items-center gap-2 text-[14.5px] font-semibold text-ov-300 hover:text-white">
                Zum Kontaktformular <ArrowRight aria-hidden="true" className="h-4 w-4" />
              </Link>
            </div>
          </aside>
        </div>
      </div>
    </div>
  );
}
// Split-Screen für Login, Registrierung, Passwort und Einladungen: links das Formular auf ruhigem Weiß,
// rechts die Markenfläche (Navy-Verlauf) mit dem animierten Marken-Motiv von T7, Nutzenversprechen je Rolle
// und Vertrauenspunkten. Auf dem Handy steht das Formular zuerst, die Markenfläche folgt kompakt darunter.
// Server-Komponente; wird innerhalb des normalen Seitenkopfs/-fußes gerendert.

import { BadgeCheck, Check, Clock, FileLock2, MessagesSquare } from "lucide-react";
import { PROVISION } from "@/lib/invest/markt";
import { ROLLEN } from "@/lib/plattform/konstanten";
import { MarkenMotiv } from "@/components/illustrationen/marke";

const NUTZEN = {
  flaeche: ["Kostenlose Vorprüfung Ihrer Fläche", "Pachtangebot direkt im Portal", "Status von der Prüfung bis zum Betrieb"],
  landwirt: ["Agri-PV: verpachten, selbst investieren oder beteiligen", "Landwirtschaft bleibt Hauptnutzung", "Ein fester Ansprechpartner"],
  investor: ["Suchprofil mit Matching-Score", "NDA per Klick, Datenraum im Portal", PROVISION.kaeufer.text.charAt(0).toUpperCase() + PROVISION.kaeufer.text.slice(1)],
  anbieter: ["Anonymer Teaser, Datenraum nach NDA", "Aufrufe, Merker und NDA-Anfragen live", `Provision ${PROVISION.verkaeufer.text}`],
  unternehmen: ["Reststrom-Pool, Solarcarport, Speicher", "Angebote und Unterlagen an einem Ort", "Status jederzeit einsehbar"],
  mitglied: ["Genossenschaft und Energiegemeinschaften", "Beteiligung und Status einsehen", "Nachrichten an einem Ort"],
  kommune: ["Projekte im Gemeindegebiet ab Planung", "Beteiligungsmodelle und § 6 EEG im Überblick", "Fester Ansprechpartner für Verwaltung und Gemeinderat"],
};

const VERTRAUEN = [
  { icon: BadgeCheck, t: "ÖKOVOLT Gruppe", s: "seit 2010" },
  { icon: FileLock2, t: "Vertraulich", s: "Datenraum nach NDA" },
  { icon: MessagesSquare, t: "Direkter Draht", s: "Nachrichten im Portal" },
];

export default function AuthRahmen({ eyebrow, titel, text, rolle, children }) {
  const r = ROLLEN.find((x) => x.id === rolle);
  const punkte = NUTZEN[rolle] || [
    "Status aller Anfragen, Flächen und Projekte",
    "Dokumente und Nachrichten sicher an einem Ort",
    "Für Flächeneigentümer und Investoren kostenfrei",
  ];
  return (
    <section className="relative overflow-hidden bg-sand-50">
      <div aria-hidden="true" className="ov-grid-bg-light pointer-events-none absolute inset-0" />
      <div className="ov-container relative py-6 sm:py-10 md:py-14">
        <div className="grid overflow-hidden rounded-[2rem] bg-white shadow-e3 ring-1 ring-ink-200/70 lg:grid-cols-[minmax(0,1.08fr)_minmax(0,0.92fr)]">
          {/* Formularseite */}
          <div className="min-w-0 px-5 py-8 sm:px-10 sm:py-12 lg:px-14 lg:py-16 xl:px-20">
            <div className="ov-ein mx-auto w-full max-w-[32rem]">
              {eyebrow && <p className="ov-overline text-ov-700">{eyebrow}</p>}
              <h1 className="mt-2 font-display text-[28px] font-extrabold leading-[1.1] tracking-tight text-ink-900 md:text-[36px]">{titel}</h1>
              {text && <p className="mt-3 text-[15.5px] leading-relaxed text-ink-600">{text}</p>}
              <div className="mt-8">{children}</div>
            </div>
          </div>

          {/* Markenseite */}
          <aside aria-label="Ihre Vorteile im Portal" className="ov-verlauf-nacht relative isolate min-w-0 overflow-hidden px-6 py-8 text-white sm:px-10 sm:py-10 lg:px-12 lg:py-14">
            <div aria-hidden="true" className="ov-grid-bg absolute inset-0 -z-10 opacity-60" />
            <div className="flex h-full flex-col">
              <div aria-hidden="true" className="relative mx-auto hidden w-full max-w-[22rem] sm:block" style={{ aspectRatio: "1 / 1" }}>
                <MarkenMotiv ton="dunkel" className="absolute inset-0 h-full w-full" />
              </div>
              <p className="ov-overline mt-2 text-ov-300 sm:mt-6">{r ? `Portal für ${r.label}` : "Ein Login für alles"}</p>
              <p className="mt-3 font-display text-[24px] font-extrabold leading-tight tracking-tight md:text-[30px]">
                Flächen. Projekte. Kapital. Strom. <span className="text-ov-300">An einem Ort.</span>
              </p>
              <ul className="mt-6 space-y-3.5">
                {punkte.map((p, i) => (
                  <li key={p} className="ov-ein flex items-start gap-3 text-[15px] leading-relaxed text-white/85" style={{ "--ov-delay": `${160 + i * 70}ms` }}>
                    <span className="mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-ov-300/15 text-ov-300 ring-1 ring-ov-300/30">
                      <Check aria-hidden="true" className="h-3.5 w-3.5" strokeWidth={3} />
                    </span>
                    <span className="min-w-0">{p}</span>
                  </li>
                ))}
              </ul>
              <div className="mt-8 grid gap-2.5 sm:grid-cols-3 lg:mt-auto lg:pt-10">
                {VERTRAUEN.map((k) => {
                  const Icon = k.icon;
                  return (
                    <div key={k.t} className="ov-glass rounded-2xl p-3.5">
                      <Icon aria-hidden="true" className="h-[18px] w-[18px] text-ov-300" />
                      <p className="mt-2 text-[14px] font-semibold">{k.t}</p>
                      <p className="text-[12.5px] text-white/75">{k.s}</p>
                    </div>
                  );
                })}
              </div>
              <p className="mt-5 flex items-center gap-2 text-[13px] text-white/75">
                <Clock aria-hidden="true" className="h-3.5 w-3.5" /> Antwort in der Regel innerhalb von zwei Werktagen
              </p>
            </div>
          </aside>
        </div>
      </div>
    </section>
  );
}
import { redirect } from "next/navigation";
import AuthRahmen from "@/components/Plattform/AuthRahmen";
import LoginFormular from "@/components/Plattform/LoginFormular";
import { abs } from "@/data/site";
import { aktuellerNutzer } from "@/lib/plattform/server/seite";
